package az.smartbee.pixel

import org.json.JSONArray
import org.json.JSONObject

/**
 * SDK-nın bütün məntiqi. Android-dən asılı deyil və axın (thread) yaratmır:
 * bütün metodlar bir axından ardıcıl çağırılmalıdır (bunu [SmartBee] təmin edir).
 */
internal class Core(
    private val key: String,
    private val options: SmartBeeOptions,
    private val store: Store,
    private val queue: EventQueue,
    private val transport: Transport,
    private val env: Env,
) {
    private val endpoint = options.endpoint.trimEnd('/')
    var config: RemoteConfig = RemoteConfig.DEFAULT
        private set
    private var analytics = true
    private var ads = true
    private var anonId = ""
    private var userId: String? = null
    private var screenName: String? = null
    private var inSessionStart = false
    private var failures = 0
    private var nextAttemptAt = 0L
    private var started = false

    /** Razılıq yoxdursa null. */
    val anonymousId: String? get() = if (started && analytics) anonId else null

    val flushIntervalMs: Long get() = config.flushIntervalMs

    private val autoEvents: Boolean get() = options.autoEvents

    private fun log(message: String) {
        if (options.debug) env.log(message)
    }

    // ---- Başlanğıc ----------------------------------------------------------------------------

    fun start() {
        config = RemoteConfig.parse(store.get(K_CONFIG)) ?: RemoteConfig.DEFAULT
        loadConsent()
        if (analytics) {
            anonId = store.get(K_ANON)?.takeIf { Util.ID_RE.matches(it) } ?: env.uuid().also { store.put(K_ANON, it) }
            userId = store.get(K_USER)
        } else {
            anonId = env.uuid()
        }
        started = true
        if (!config.enabled) queue.clear()
        lifecycleVersionEvents()
    }

    private fun loadConsent() {
        analytics = config.consentAnalytics
        ads = config.consentAds
        options.consent?.let { analytics = it.analytics; ads = it.ads }
        val saved = store.get(K_CONSENT)
        if (saved != null && saved.length == 2) {
            analytics = saved[0] == '1'
            ads = saved[1] == '1'
        }
    }

    /** İlk açılışda AppInstall, versiya dəyişəndən sonrakı ilk açılışda AppUpdate. */
    private fun lifecycleVersionEvents() {
        if (!analytics) return
        val app = env.deviceContext().optJSONObject("app") ?: return
        val current = app.optString("version") + "|" + app.optString("build")
        val previous = store.get(K_APP_VERSION)
        if (previous == current) return
        store.put(K_APP_VERSION, current)
        if (!autoEvents || !config.auto("lifecycle")) return
        if (previous == null) {
            track("AppInstall", null, null, ORIGIN_AUTO)
        } else {
            track("AppUpdate", mapOf("previous_version" to previous.substringBefore('|'), "previous_build" to previous.substringAfter('|')), null, ORIGIN_AUTO)
        }
    }

    // ---- Açıq əməliyyatlar --------------------------------------------------------------------

    fun track(name: String?, props: Map<String, Any?>?, eventId: String?, origin: String = ORIGIN_CODE) {
        if (!started || !analytics || !config.enabled) return
        if (name == null || !Util.NAME_RE.matches(name)) {
            log("invalid event name: $name")
            return
        }
        if (config.blockedEvents.contains(name) || sampledOut()) return
        val event = base("track", origin)
        event.put("name", name)
        if (eventId != null && Util.ID_RE.matches(eventId)) event.put("id", eventId)
        Util.cleanObject(props, ::log)?.let { event.put("props", it) }
        enqueue(event)
    }

    fun identify(id: String?, traits: Map<String, Any?>?) {
        if (!started || !analytics || !config.enabled) return
        if (id.isNullOrEmpty() || id.length > 128) {
            log("invalid user id")
            return
        }
        userId = id
        store.put(K_USER, id)
        if (sampledOut()) return
        val event = base("identify", ORIGIN_CODE)
        event.put("user_id", id)
        val out = Util.cleanObject(traits, ::log) ?: JSONObject()
        // E-poçt və telefon cihazı yalnız hash şəklində tərk edir.
        (traits?.get("email") as? String)?.let { Util.normalizeEmail(it) }?.takeIf { it.isNotEmpty() }?.let { out.put("email_sha256", Util.sha256(it)) }
        traits?.get("phone")?.takeIf { it is String || it is Number }?.let { Util.normalizePhone(it.toString()) }?.takeIf { it.isNotEmpty() }
            ?.let { out.put("phone_sha256", Util.sha256(it)) }
        if (out.length() > 0) event.put("traits", out)
        enqueue(event)
    }

    fun screen(name: String?, props: Map<String, Any?>?, origin: String = ORIGIN_CODE) {
        if (name.isNullOrEmpty()) return
        screenName = name.take(128)
        if (origin == ORIGIN_AUTO && (!autoEvents || !config.auto("screens"))) return
        track("ScreenView", props, null, origin)
    }

    fun setConsent(newAnalytics: Boolean?, newAds: Boolean?) {
        if (!started) return
        val was = analytics
        newAnalytics?.let { analytics = it }
        newAds?.let { ads = it }
        store.put(K_CONSENT, (if (analytics) "1" else "0") + (if (ads) "1" else "0"))
        if (!analytics) {
            queue.clear()
            for (k in listOf(K_ANON, K_USER, K_SESSION, K_SEQ, K_CAMPAIGN)) store.remove(k)
            userId = null
        } else if (!was) {
            store.put(K_ANON, anonId)
        }
    }

    fun reset() {
        if (!started) return
        flush(force = true)
        userId = null
        store.remove(K_USER)
        store.remove(K_SESSION)
        anonId = env.uuid()
        if (analytics) store.put(K_ANON, anonId)
    }

    /** Tətbiq ön plana keçdi. */
    fun onForeground() {
        if (!started) return
        refreshConfig()
        if (autoEvents && config.auto("lifecycle")) track("AppOpen", null, null, ORIGIN_AUTO)
        flush()
    }

    /** Tətbiq arxa fona keçdi: növbə dərhal göndərilir. */
    fun onBackground() {
        if (started) flush(force = true)
    }

    fun onDeepLink(url: String?) {
        if (!started || url.isNullOrEmpty() || !analytics) return
        Util.campaignOf(url)?.let { store.put(K_CAMPAIGN, it.toString()) }
        if (autoEvents && config.auto("deeplinks")) {
            track("DeepLinkOpen", mapOf("url" to Util.cleanUrl(url, config.stripParams)), null, ORIGIN_AUTO)
        }
    }

    // ---- Eventin qurulması --------------------------------------------------------------------

    private fun sampledOut(): Boolean = config.sample < 1.0 && Util.fraction(anonId) >= config.sample

    private fun session(now: Long): String {
        val raw = store.get(K_SESSION).orEmpty()
        val sep = raw.lastIndexOf('|')
        var id = if (sep > 0) raw.substring(0, sep) else ""
        val last = if (sep > 0) raw.substring(sep + 1).toLongOrNull() ?: 0L else 0L
        val fresh = id.isEmpty() || !Util.ID_RE.matches(id) || last == 0L || now - last > config.sessionTimeoutMs || now < last - 60_000
        if (fresh) id = env.uuid()
        store.put(K_SESSION, "$id|$now")
        if (fresh && !inSessionStart && autoEvents) {
            inSessionStart = true
            try {
                track("SessionStart", null, null, ORIGIN_AUTO)
            } finally {
                inSessionStart = false
            }
        }
        return id
    }

    private fun nextSeq(): Long {
        val next = (store.get(K_SEQ)?.toLongOrNull() ?: -1L) + 1
        store.put(K_SEQ, next.toString())
        return next
    }

    private fun base(type: String, origin: String): JSONObject {
        val now = env.now()
        val sessionId = session(now)
        val event = JSONObject()
        event.put("id", env.uuid())
        event.put("type", type)
        event.put("ts", Util.iso(now))
        event.put("anon_id", anonId)
        event.put("session_id", sessionId)
        event.put("seq", nextSeq())
        userId?.let { event.put("user_id", it) }
        if (origin != ORIGIN_CODE) event.put("origin", origin)
        screenName?.let { event.put("screen", JSONObject().put("name", it)) }
        return event
    }

    private fun context(): String {
        val ctx = env.deviceContext()
        ctx.put("platform", "android")
        ctx.put("consent", JSONObject().put("analytics", analytics).put("ads", ads))
        val saved = store.get(K_CAMPAIGN)
        if (saved != null) {
            try {
                val campaign = JSONObject(saved)
                // Reklam razılığı yoxdursa klik ID-ləri göndərilmir.
                if (!ads) for (id in Util.CLICK_IDS) campaign.remove(id)
                if (campaign.length() > 0) ctx.put("campaign", campaign)
            } catch (e: Exception) {
                store.remove(K_CAMPAIGN)
            }
        }
        return ctx.toString()
    }

    private fun enqueue(event: JSONObject) {
        val payload = event.toString()
        if (payload.toByteArray(Charsets.UTF_8).size > MAX_EVENT_BYTES) {
            log("event too large, dropped: " + event.optString("name"))
            return
        }
        queue.add(context(), payload)
        queue.trim(config.maxQueue)
        if (queue.size() >= config.maxBatch) flush()
    }

    // ---- Göndərmə -----------------------------------------------------------------------------

    /**
     * Növbəni toplu-toplu göndərir. Uğursuzluqdan sonra artan fasilə gözlənilir;
     * `force` bu fasiləni nəzərə almır (arxa fona keçid, əl ilə flush).
     */
    fun flush(force: Boolean = false) {
        if (!started) return
        if (!analytics || !config.enabled) {
            queue.clear()
            return
        }
        val now = env.now()
        if (!force && now < nextAttemptAt) return
        var rounds = 0
        while (rounds++ < MAX_BATCHES_PER_FLUSH) {
            val rows = queue.peek(config.maxBatch)
            if (rows.isEmpty()) return
            // Eyni kontekstli ardıcıl eventlər bir topluya düşür (PROTOCOL.md 5.3).
            val ctx = rows[0].ctx
            val batch = ArrayList<QueuedEvent>()
            var bytes = ctx.length + 256
            for (row in rows) {
                if (row.ctx != ctx || (batch.isNotEmpty() && bytes + row.payload.length > MAX_BODY_BYTES)) break
                batch.add(row)
                bytes += row.payload.length + 1
            }
            val result = try {
                transport.post("$endpoint/v1/e", body(ctx, batch))
            } catch (e: Exception) {
                HttpResult(-1)
            }
            if (result.retryable) {
                failures++
                val backoff = minOf(BACKOFF_BASE_MS shl minOf(failures - 1, 20), BACKOFF_MAX_MS)
                val wait = result.retryAfterSec?.let { it.coerceIn(1, 3600) * 1000 } ?: (backoff * (0.8 + Math.random() * 0.4)).toLong()
                nextAttemptAt = now + wait
                log("send failed (${result.status}), retry in ${wait}ms")
                return
            }
            // 2xx: qəbul olundu. Digər 4xx: toplu yararsızdır, təkrar göndərilmir.
            if (!result.ok) log("batch rejected (${result.status}), dropped ${batch.size} events")
            failures = 0
            nextAttemptAt = 0
            queue.remove(batch.map { it.id })
        }
    }

    private fun body(ctx: String, batch: List<QueuedEvent>): String {
        val events = JSONArray()
        for (row in batch) events.put(JSONObject(row.payload))
        val sdk = JSONObject().put("name", "android").put("version", SDK_VERSION)
        options.wrapper?.let { sdk.put("wrapper", it) }
        options.wrapperVersion?.let { sdk.put("wrapper_version", it) }
        return JSONObject()
            .put("v", 1)
            .put("key", key)
            .put("sent_at", Util.iso(env.now()))
            .put("sdk", sdk)
            .put("ctx", JSONObject(ctx))
            .put("events", events)
            .toString()
    }

    // ---- Konfiq -------------------------------------------------------------------------------

    /** Konfiq köhnəlibsə serverdən yeniləyir. 404: mənbə naməlum və ya söndürülüb. */
    fun refreshConfig(force: Boolean = false) {
        if (!started) return
        val now = env.now()
        val fetchedAt = store.get(K_CONFIG_AT)?.toLongOrNull() ?: 0L
        if (!force && fetchedAt != 0L && now - fetchedAt in 0 until config.ttlMs) return
        val result = try {
            transport.get("$endpoint/v1/$key/config", store.get(K_CONFIG_ETAG))
        } catch (e: Exception) {
            HttpResult(-1)
        }
        when {
            result.status == 200 -> {
                val parsed = RemoteConfig.parse(result.body) ?: return
                config = parsed
                store.put(K_CONFIG, result.body.orEmpty())
                result.etag?.let { store.put(K_CONFIG_ETAG, it) } ?: store.remove(K_CONFIG_ETAG)
                store.put(K_CONFIG_AT, now.toString())
            }
            result.status == 304 -> store.put(K_CONFIG_AT, now.toString())
            result.status == 404 -> {
                config = RemoteConfig.DISABLED
                store.put(K_CONFIG, "{\"enabled\":false,\"ttl_s\":86400}")
                store.remove(K_CONFIG_ETAG)
                store.put(K_CONFIG_AT, now.toString())
            }
            else -> return
        }
        if (!config.enabled) queue.clear()
    }

    companion object {
        const val ORIGIN_CODE = "code"
        const val ORIGIN_AUTO = "auto"
        const val MAX_EVENT_BYTES = 32_000
        const val MAX_BODY_BYTES = 450_000
        const val MAX_BATCHES_PER_FLUSH = 20
        const val BACKOFF_BASE_MS = 5_000L
        const val BACKOFF_MAX_MS = 3_600_000L

        const val K_ANON = "anon_id"
        const val K_USER = "user_id"
        const val K_SESSION = "session"
        const val K_SEQ = "seq"
        const val K_CONSENT = "consent"
        const val K_CAMPAIGN = "campaign"
        const val K_APP_VERSION = "app_version"
        const val K_CONFIG = "config"
        const val K_CONFIG_ETAG = "config_etag"
        const val K_CONFIG_AT = "config_at"
